901      static private List<Set<FType>> overlapPieces(FType p, FType q, Set<List<FType>> path, int[] steps) {
902          if (--steps[0] < 0) return null;
903          if (p instanceof SymbolicType || q instanceof SymbolicType) return null;
904          List<Set<FType>> res = new ArrayList<Set<FType>>();
905          try {
906              if (p.subtypeOf(q)) {
907                  res.add(Collections.singleton(p));
908                  return res;
909              }
910              if (q.subtypeOf(p)) {
911                  res.add(Collections.singleton(q));
912                  return res;
913              }
914              if (p.excludesOther(q)) return res;
915              Set<FType> pc = p.getComprises();
916              Set<FType> qc = q.getComprises();
917              if (pc == null && qc == null) {
918                  Set<FType> both = new HashSet<FType>();
919                  both.add(p);
920                  both.add(q);
921                  res.add(both);
922                  return res;
923              }
924              List<FType> key = Useful.<FType>list(p, q);
925              if (!path.add(key)) return null;
926              if (pc != null) {
927                  for (FType c : pc) {
928                      List<Set<FType>> sub = overlapPieces(c, q, path, steps);
929                      if (sub == null) return null;
930                      res.addAll(sub);
931                  }
932              } else {
933                  for (FType c : qc) {
934                      List<Set<FType>> sub = overlapPieces(p, c, path, steps);
935                      if (sub == null) return null;
936                      res.addAll(sub);
937                  }
938              }
939              path.remove(key);
940              return res;
941          }
942          catch (FortressException ex) {
943              return null;
944          }
945      }

