        inner.doDefs1234(defs);
        membersInitialized = true;
    }

    public BetterEnv getMembers() {
        if (!membersInitialized) {
            synchronized (this) {
                if (!membersInitialized) {
                    initializeMembers();
                }
            }
        }
        return declaredMembersOf;
    }

    protected BetterEnv getMembersInternal() {
        return declaredMembersOf;
