            exclDumpln("Excludes.  Neither can be extended.");
            return true;
        }
        if (this.getExcludes().contains(other)) {
            exclDumpln("Excludes (cached).");
            return true;
        }
        if (other.getExcludes().contains(this)) {
            exclDumpln("Other excludes (transitive closure just happened).");
            return true;
        }
        return false;
